    /**
     * Get the minimal sidebar for supplier portal logins: one item per profile section, then notifications.
     */
    public static function getSupplierPortalGroups(?string $notificationBadge = null): array
    {
        $sectionItems = [];

        foreach (SupplierProfileData::SECTIONS as $sectionKey => $section) {
            $sectionItems[] = [
                'icon' => 'supplier-'.$sectionKey,
                'name' => $section['label'],
                'path' => '/my-supplier-profile/'.$sectionKey,
            ];
        }

        return [
            [
                'title' => 'Menu',
                'items' => [
                    ...$sectionItems,
                    [
                        'icon' => 'bell',
                        'name' => 'Notifications',
                        'path' => '/notifications',
                        'badge' => $notificationBadge,
                    ],
                ],
            ],
        ];
    }

    /**
     * Get all menu groups for the sidebar.
     */
    public static function getMenuGroups(): array
    {
        $groups = [
            [
                'title' => 'Menu',
                'items' => self::getMainNavItems(),
            ],
        ];

        return $groups;
    }

    public static function isActive(string $path): bool
    {
        $trimmed = ltrim($path, '/');

        // Route supplier edit page to the "New Supplier" (Add/Update Suppliers) menu item
        if ($trimmed === 'suppliers/create' && request()->routeIs('suppliers.edit')) {
            return true;
        }

        if ($trimmed === 'suppliers' && request()->routeIs('suppliers.edit')) {
            return false;
        }

        // Route customer edit page to the "New Customer" (Add/Update Customers) menu item
        if ($trimmed === 'customers/create' && request()->routeIs('customers.edit')) {
            return true;
        }

        if ($trimmed === 'customers' && request()->routeIs('customers.edit')) {
            return false;
        }

        return request()->is($trimmed) || request()->is($trimmed.'/*');
    }

